CREATE TABLE projects (project_id varchar(64) PRIMARY KEY, display_name varchar(120) NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE instances (project_id varchar(64) NOT NULL REFERENCES projects(project_id), instance_id varchar(64) NOT NULL, display_name varchar(120) NOT NULL, environment varchar(40), agent_base_url varchar(500) NOT NULL, token_ciphertext bytea NOT NULL, token_iv bytea NOT NULL, api_checks_enabled boolean NOT NULL DEFAULT false, poll_interval_seconds integer NOT NULL DEFAULT 15 CHECK (poll_interval_seconds >= 15), enabled boolean NOT NULL DEFAULT true, last_seen_at timestamptz, consecutive_failures integer NOT NULL DEFAULT 0, last_collection_error_code varchar(40), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,instance_id), UNIQUE(agent_base_url));
CREATE TABLE instance_snapshot_latest (project_id varchar(64) NOT NULL, instance_id varchar(64) NOT NULL, central_received_at timestamptz NOT NULL, agent_observed_at timestamptz NOT NULL, status varchar(10) NOT NULL, status_reason varchar(80), pid bigint, jvm_start_time timestamptz, uptime_ms bigint, system_cpu_ratio numeric, process_cpu_ratio numeric, heap_used_bytes bigint, heap_max_bytes bigint, non_heap_used_bytes bigint, thread_live_count integer, thread_peak_count integer, gc_count bigint, gc_time_ms bigint, physical_memory_used_bytes bigint, physical_memory_total_bytes bigint, extra_json jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(project_id,instance_id), FOREIGN KEY(project_id,instance_id) REFERENCES instances(project_id,instance_id));
CREATE TABLE instance_metric_samples (sampled_at timestamptz NOT NULL, project_id varchar(64) NOT NULL, instance_id varchar(64) NOT NULL, system_cpu_ratio numeric, process_cpu_ratio numeric, heap_used_bytes bigint, heap_max_bytes bigint, physical_memory_used_bytes bigint, physical_memory_total_bytes bigint, thread_live_count integer, gc_count bigint, gc_time_ms bigint, PRIMARY KEY(project_id,instance_id,sampled_at), FOREIGN KEY(project_id,instance_id) REFERENCES instances(project_id,instance_id));
CREATE INDEX instance_metric_samples_lookup ON instance_metric_samples(project_id,instance_id,sampled_at DESC);
CREATE TABLE disk_latest (project_id varchar(64), instance_id varchar(64), path_id varchar(64), path_display varchar(500), used_bytes bigint, total_bytes bigint, status varchar(10), PRIMARY KEY(project_id,instance_id,path_id), FOREIGN KEY(project_id,instance_id) REFERENCES instances(project_id,instance_id));
CREATE TABLE disk_samples (sampled_at timestamptz, project_id varchar(64), instance_id varchar(64), path_id varchar(64), used_bytes bigint, total_bytes bigint, status varchar(10), PRIMARY KEY(project_id,instance_id,path_id,sampled_at));
CREATE TABLE db_pool_latest (project_id varchar(64), instance_id varchar(64), pool_id varchar(64), name varchar(120), active integer, idle integer, max_size integer, min_idle integer, waiters integer, max_wait_ms bigint, validation_latency_ms bigint, status varchar(10), PRIMARY KEY(project_id,instance_id,pool_id), FOREIGN KEY(project_id,instance_id) REFERENCES instances(project_id,instance_id));
CREATE TABLE db_pool_samples (sampled_at timestamptz, project_id varchar(64), instance_id varchar(64), pool_id varchar(64), active integer, idle integer, max_size integer, waiters integer, validation_latency_ms bigint, status varchar(10), PRIMARY KEY(project_id,instance_id,pool_id,sampled_at));
CREATE TABLE check_definitions (project_id varchar(64), instance_id varchar(64), check_id varchar(64), name varchar(120) NOT NULL, category varchar(20) NOT NULL, direction varchar(20), enabled boolean NOT NULL DEFAULT true, discovered_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL, PRIMARY KEY(project_id,instance_id,check_id), FOREIGN KEY(project_id,instance_id) REFERENCES instances(project_id,instance_id));
CREATE TABLE check_results_latest (project_id varchar(64), instance_id varchar(64), check_id varchar(64), status varchar(10), duration_ms bigint, result_code varchar(40), message varchar(500), checked_at timestamptz, central_received_at timestamptz, PRIMARY KEY(project_id,instance_id,check_id));
CREATE TABLE check_result_samples (project_id varchar(64), instance_id varchar(64), check_id varchar(64), checked_at timestamptz, status varchar(10), duration_ms bigint, result_code varchar(40), message varchar(500), central_received_at timestamptz, PRIMARY KEY(project_id,instance_id,check_id,checked_at));
CREATE TABLE certificate_targets (certificate_target_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, project_id varchar(64) NOT NULL REFERENCES projects(project_id), hostname varchar(253) NOT NULL, port integer NOT NULL CHECK(port BETWEEN 1 AND 65535), sni_hostname varchar(253) NOT NULL, enabled boolean NOT NULL DEFAULT true, check_interval_minutes integer NOT NULL DEFAULT 360, UNIQUE(project_id,hostname,port,sni_hostname));
CREATE TABLE certificate_latest (certificate_target_id bigint PRIMARY KEY REFERENCES certificate_targets(certificate_target_id), subject varchar(500), issuer varchar(500), serial_number varchar(200), not_before timestamptz, not_after timestamptz, days_remaining integer, chain_valid boolean, hostname_valid boolean, signature_algorithm varchar(100), status varchar(10), message varchar(500), checked_at timestamptz);
CREATE TABLE app_users (username varchar(80) PRIMARY KEY, password_hash varchar(100) NOT NULL, role varchar(20) NOT NULL CHECK(role='ADMIN'), enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_login_at timestamptz);
CREATE TABLE thresholds (scope varchar(10) NOT NULL, project_id varchar(64), instance_id varchar(64), metric_key varchar(50) NOT NULL, warning_value numeric NOT NULL, critical_value numeric NOT NULL, updated_at timestamptz NOT NULL DEFAULT now(), CHECK ((scope='GLOBAL' AND project_id IS NULL AND instance_id IS NULL) OR (scope='PROJECT' AND project_id IS NOT NULL AND instance_id IS NULL) OR (scope='INSTANCE' AND project_id IS NOT NULL AND instance_id IS NOT NULL)), UNIQUE NULLS NOT DISTINCT(scope,project_id,instance_id,metric_key));
